    /** The exact item identity for a numeric build item ID, or null. */
    fun get(id: Int): HnsItemData? = byId[id]

    /** The exact item identity for an `ITEM_*` source symbol, or null. */
    fun getBySymbol(symbol: String): HnsItemData? = bySymbol[symbol]

    /**
     * Resolves a user-facing/source item name to its exact build identity.
     *
     * Matching is case-insensitive and ignores hyphens and repeated spaces.
     * A name shared by more than one ID resolves to null (fail closed), and
     * a name not present in this exact build resolves to null as well.
     */
    fun getByName(name: String?): HnsItemData? {
        if (name.isNullOrBlank()) return null
        return byNormalizedName[normalize(name)]
