    internal fun normalize(raw: String): String =
        raw.trim().lowercase().replace('-', ' ').replace(Regex("\\s+"), " ")

    private fun register(
        id: Int,
        symbol: String,
        sourceName: String?,
        holdEffect: String,
        holdEffectParam: Int
    ) {
        val data = HnsItemData(id, symbol, sourceName, holdEffect, holdEffectParam)
        byId[id] = data
        bySymbol[symbol] = data
        if (sourceName != null) {
            val key = normalize(sourceName)
            // A name that is not unique in this build is never resolved.
            if (byNormalizedName.containsKey(key)) {
                byNormalizedName[key] = null
            } else {
                byNormalizedName[key] = data
            }
        }
    }

